<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { useAuthStore } from '../sessionStore';import DsButton from '@/shared/ui/DsButton.vue';import DsCard from '@/shared/ui/DsCard.vue';import DsInput from '@/shared/ui/DsInput.vue'
const email=ref('');const password=ref('');const error=ref('');const busy=ref(false);const auth=useAuthStore();const router=useRouter();async function submit(){busy.value=true;error.value='';try{await auth.login(email.value,password.value);await router.replace('/')}catch(e){error.value=e instanceof Error?e.message:'Unable to sign in.'}finally{busy.value=false}}
</script>
<template><main class="login"><DsCard class="card"><form @submit.prevent="submit"><p class="eyebrow">FULLSTACK STARTER</p><h1>Welcome back</h1><p class="muted">Sign in to continue to the administration workspace.</p><div class="fields"><DsInput v-model="email" label="Email" type="email" autocomplete="username"/><DsInput v-model="password" label="Password" type="password" autocomplete="current-password"/></div><p v-if="error" class="error">{{error}}</p><DsButton type="submit" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</DsButton></form></DsCard></main></template>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--ds-canvas)}.card{width:min(420px,100%)}h1{margin:4px 0 8px;font-size:32px}.eyebrow{margin:0;color:var(--ds-brand);font-size:12px;font-weight:700;letter-spacing:.12em}.muted{margin:0 0 28px;color:var(--ds-text-secondary)}.fields{display:grid;gap:16px}.error{color:var(--ds-danger);font-size:14px}.card :deep(.ds-button){width:100%;margin-top:8px}</style>
